import {
    Table,
    IntegerColumn,
    StringColumn,
    SystemClassNameColumn,
    ReferenceColumn,
    GenericColumn,
    DateTimeColumn,
} from '../../db'

export const sys_metadata = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.forcePrimaryKeyOrdering': true,
        'all_tables.include_auto_recovery': true,
        'all_tables.text_index_translations': true,
        kagami_csindex_enabled: true,
        no_data_replicate: true,
        no_labels: true,
        text_index_default_partial_matching_rule: '-25%',
        text_index_default_query_mode: 'IR_AND_OR_QUERY',
        text_index_enable_idf: true,
    },
    extensible: true,
    label: 'Application File',
    name: 'sys_metadata',
    schema: {
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                },
            ],
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                },
            ],
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Class',
            maxLength: 80,
        }),
        sys_package: ReferenceColumn({
            attributes: {
                readonly_clickthrough: true,
            },
            cascadeRule: 'none',
            label: 'Package',
            readOnly: true,
            readOnlyOption: 'strict_read_only',
            referenceTable: 'sys_package',
        }),
        sys_policy: StringColumn({
            attributes: {
                plugin_upgrade_update_only: true,
            },
            choices: {
                read: {
                    label: 'Read-only',
                    sequence: 1,
                },
                protected: {
                    label: 'Protected',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Determines how application files are protected when downloaded or installed',
                    label: 'Protection policy',
                    plural: 'Protection policies',
                },
            ],
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                },
            ],
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                },
            ],
        }),
        sys_update_name: StringColumn({
            label: 'Update name',
            maxLength: 250,
        }),
        sys_scope: ReferenceColumn({
            attributes: {
                ignore_filter_on_new: true,
                list_force_default: true,
                readonly_clickthrough: true,
            },
            cascadeRule: 'none',
            default:
                "javascript:(((typeof parent == 'object') && parent != null && parent.getTableName() == 'sys_app') ? parent.sys_id : gs.getCurrentApplicationId())",
            label: [
                {
                    hint: 'Application containing this record',
                    label: 'Application',
                    plural: 'Applications',
                },
            ],
            referenceTable: 'sys_scope',
        }),
        sys_name: StringColumn({
            label: [
                {
                    hint: 'Display name for this application file',
                    label: 'Display name',
                    plural: 'Display names',
                },
            ],
            maxLength: 255,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                },
            ],
        }),
    },
    textIndex: true,
})
